import{_ as t,o,c as d,a3 as a}from"./chunks/framework.B_jDsKE8.js";const u=JSON.parse('{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/env-vars.md","filePath":"reference/env-vars.md"}'),r={name:"reference/env-vars.md"};function n(i,e,c,l,s,f){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Var</th><th>Read by</th><th>Effect</th></tr></thead><tbody><tr><td><code>TARDIGRADA_IDENTITY_BACKEND</code></td><td>backend selection</td><td><code>keyring</code> (default, fail closed) | <code>auto</code> (keyring → keyfile fallback) | <code>file</code> (keyfile only). Unrecognized values warn on stderr (<code>{&quot;warning&quot;: …}</code> under <code>--json</code>) and mean <code>keyring</code>.</td></tr><tr><td><code>TARDIGRADA_IDENTITY_FILE</code></td><td>path resolution + pin</td><td>Keyfile path override (empty = ignored). A non-empty value pins the file backend — the keyring is never probed.</td></tr><tr><td><code>CUORA_IDENTITY_FILE</code> / <code>ARCA_IDENTITY_FILE</code></td><td>path resolution + pin</td><td>Legacy keyfile pins, honored identically to <code>TARDIGRADA_IDENTITY_FILE</code> — a non-empty value pins the file backend so tardigrada and cuora can never split onto different identities. Same-uid trust: whoever can set env can already read the keyfile.</td></tr><tr><td><code>XDG_CONFIG_HOME</code></td><td>path resolution</td><td>Config root — default keyfile is <code>$XDG_CONFIG_HOME/tardigrada/identity.txt</code></td></tr><tr><td><code>HOME</code></td><td>path resolution</td><td>Fallback config root <code>~/.config/…</code> when <code>XDG_CONFIG_HOME</code> is unset</td></tr><tr><td><code>CUORA_KEYRING_TIMEOUT_MS</code></td><td><code>cuora-identity-keyring</code></td><td>Bounds one keyring op in ms (<code>0</code> waits forever); default 120s.</td></tr></tbody></table><h2 id="backend-selection" tabindex="-1">Backend selection <a class="header-anchor" href="#backend-selection" aria-label="Permalink to &quot;Backend selection&quot;">​</a></h2><p><code>TARDIGRADA_IDENTITY_BACKEND</code> picks the store, mirroring cuora:</p><ul><li><strong><code>keyring</code></strong> (default) — the platform session secret store, entry <code>tardigrada/age-identity</code> (legacy <code>cuora</code>/<code>arca</code> entries read as fallbacks). <strong>Fail closed</strong>: an unreachable store is an error, never a silent keyfile read.</li><li><strong><code>auto</code></strong> — keyring when reachable; an unreachable store, an unreadable entry, or an empty store falls back to the keyfile (with a stderr note on failures). The headless/CI mode.</li><li><strong><code>file</code></strong> — the keyfile only; the store is never probed.</li></ul><p>An explicit <code>--identity-file</code> flag, <code>TARDIGRADA_IDENTITY_FILE</code>, or a legacy <code>CUORA_IDENTITY_FILE</code>/<code>ARCA_IDENTITY_FILE</code> pin always means file and wins over every backend mode — no dbus round-trip. An env pin under <code>backend=keyring</code> (the default) emits a warning; the flag is the caller&#39;s deliberate choice and stays a quiet note. All env vars are same-uid trust — they redirect resolution freely by design, not a security boundary.</p><h2 id="keyfile-path-resolution" tabindex="-1">Keyfile path resolution <a class="header-anchor" href="#keyfile-path-resolution" aria-label="Permalink to &quot;Keyfile path resolution&quot;">​</a></h2><p>Used by the <code>file</code> backend and the <code>auto</code> fallback (the <code>cuora-identity-file</code> default):</p><ol><li><code>--identity-file PATH</code> (global flag)</li><li><code>TARDIGRADA_IDENTITY_FILE</code></li><li><code>CUORA_IDENTITY_FILE</code> / <code>ARCA_IDENTITY_FILE</code> (legacy, via the shared impl)</li><li>first existing of <code>&lt;config&gt;/tardigrada|cuora|arca/identity.txt</code> across the XDG config home and <code>~/.config</code></li><li>creation target: <code>&lt;config&gt;/tardigrada/identity.txt</code></li></ol>',9)])])}const y=t(r,[["render",n]]);export{u as __pageData,y as default};
